def _pdfium_bitmap_to_tk_photo(bitmap):
    """Convert a pypdfium2 PdfBitmap into a Tk PhotoImage."""
    try:
        pil_image = bitmap.to_pil()
    except ImportError as exc:
        raise RuntimeError(
            "PDF preview also requires Pillow. Install it with: "
            "python -m pip install pillow"
        ) from exc

    buffer = io.BytesIO()
    pil_image.save(buffer, format="PPM")
    return tk.PhotoImage(data=buffer.getvalue())


