def form2848_ensure_dirs():
    FORM2848_DIR.mkdir(parents=True, exist_ok=True)
    FORM2848_OUTPUT_DIR.mkdir(parents=True, exist_ok=True)


def form2848_safe_filename(value):
    value = str(value or "").strip() or "Taxpayer"
    value = re.sub(r"[^A-Za-z0-9._ -]+", "", value)
    value = re.sub(r"\s+", "_", value)
    return value[:80] or "Taxpayer"


def form2848_open_with_default_app(path):
    path = Path(path)
    if sys.platform.startswith("win"):
        os.startfile(str(path))
    elif sys.platform == "darwin":
        subprocess.Popen(["open", str(path)])
    else:
        subprocess.Popen(["xdg-open", str(path)])


def form2848_download_current_form(destination=FORM2848_DEFAULT_FORM_PATH):
    """Download the official IRS Form 2848 PDF safely and atomically."""
    form2848_ensure_dirs()
    destination = Path(destination)
    destination.parent.mkdir(parents=True, exist_ok=True)

    request = urllib.request.Request(
        FORM2848_IRS_URL,
        headers={
            "User-Agent": (
                "Mozilla/5.0 BabyFileCab/Form2848-0.2 "
                "(desktop tax form utility)"
            )
        },
    )

    # Limit the response size so an unexpected server response cannot consume
    # unbounded memory. The official IRS PDF is far smaller than this ceiling.
    max_download_bytes = 25 * 1024 * 1024
    with urllib.request.urlopen(request, timeout=30) as response:
        content = response.read(max_download_bytes + 1)

    if len(content) > max_download_bytes:
        raise RuntimeError("The IRS Form 2848 download was unexpectedly large.")

    if not content.startswith(b"%PDF-"):
        raise RuntimeError("The IRS download did not return a PDF file.")

    # Write to a temporary file first so a failed/interrupted update never
    # replaces a known-good local Form 2848 with a partial file.
    temporary = destination.with_name(destination.name + ".download")
    try:
        temporary.write_bytes(content)
        os.replace(temporary, destination)
    finally:
        try:
            temporary.unlink(missing_ok=True)
        except OSError:
            pass

    return destination


def form2848_get_or_download_current_form(destination=FORM2848_DEFAULT_FORM_PATH):
    """Return a usable local Form 2848, downloading it only when needed."""
    form2848_ensure_dirs()
    destination = Path(destination)

    if destination.exists():
        try:
            with destination.open("rb") as handle:
                if handle.read(5) == b"%PDF-":
                    return destination
        except OSError:
            pass

    return form2848_download_current_form(destination)


def _form2848_fitted_font_size(
    text,
    max_width,
    preferred_size,
    min_size,
    font_name="Helvetica",
):
    size = preferred_size
    while (
        size > min_size
        and form2848_string_width(text, font_name, size) > max_width
    ):
        size -= 0.2
    return max(size, min_size)


def _form2848_draw_text_fit(
    c,
    text,
    x,
    y,
    max_width,
    font_size=8.0,
    min_font_size=5.5,
    font_name="Helvetica",
):
    text = str(text or "").strip()
    if not text:
        return
    size = _form2848_fitted_font_size(
        text,
        max_width,
        font_size,
        min_font_size,
        font_name,
    )
    c.setFont(font_name, size)
    c.drawString(x, y, text)


def _form2848_draw_centered_text_fit(
    c,
    text,
    center_x,
    y,
    max_width,
    font_size=8.0,
    min_font_size=5.5,
):
    text = str(text or "").strip()
    if not text:
        return
    size = _form2848_fitted_font_size(
        text,
        max_width,
        font_size,
        min_font_size,
    )
    c.setFont("Helvetica", size)
    c.drawCentredString(center_x, y, text)


def _form2848_draw_multiline(
    c,
    lines,
    x,
    first_baseline_y,
    max_width,
    font_size=8.0,
    leading=10.5,
    max_lines=3,
):
    clean_lines = [
        str(line or "").strip()
        for line in lines
        if str(line or "").strip()
    ]
    for index, line in enumerate(clean_lines[:max_lines]):
        _form2848_draw_text_fit(
            c,
            line,
            x,
            first_baseline_y - (index * leading),
            max_width,
            font_size=font_size,
            min_font_size=5.5,
        )


def form2848_build_overlay(data):
    """Build the exact v0.2 two-page transparent Form 2848 overlay."""
    if not FORM2848_PDF_SUPPORT_AVAILABLE:
        raise RuntimeError(
            "Form 2848 support requires pypdf and reportlab. "
            "Install them with: python -m pip install pypdf reportlab"
        )

    buffer = io.BytesIO()
    c = form2848_canvas.Canvas(buffer, pagesize=FORM2848_LETTER)

    # Page 1 - taxpayer information.
    _form2848_draw_multiline(
        c,
        [data.taxpayer_name, data.taxpayer_address1, data.taxpayer_address2],
        x=37.5,
        first_baseline_y=639.5,
        max_width=292.0,
        font_size=8.0,
        leading=10.8,
    )
    _form2848_draw_text_fit(c, data.taxpayer_tin, 343.0, 639.5, 226.0, 8.0)
    _form2848_draw_text_fit(c, data.taxpayer_phone, 343.0, 613.5, 133.0, 7.8)

    # Page 1 - up to four representatives.
    rep_layouts = [
        (568.0, 576.0, 564.0, 552.0, 540.0, (276.5, 532.5)),
        (510.0, 518.0, 506.0, 494.0, 482.0, (276.5, 474.5)),
        (452.0, 460.0, 448.0, 436.0, 424.0, None),
        (394.0, 402.0, 390.0, 378.0, 366.0, None),
    ]

    for index, representative in enumerate(data.representatives[:4]):
        name_y, caf_y, ptin_y, phone_y, fax_y, notice_xy = rep_layouts[index]
        _form2848_draw_multiline(
            c,
            [representative.name, representative.address1, representative.address2],
            x=37.5,
            first_baseline_y=name_y,
            max_width=273.0,
            font_size=7.4,
            leading=9.4,
        )
        _form2848_draw_text_fit(c, representative.caf_number, 410.0, caf_y, 151.0, 7.5)
        _form2848_draw_text_fit(c, representative.ptin, 410.0, ptin_y, 151.0, 7.5)
        _form2848_draw_text_fit(c, representative.phone, 423.0, phone_y, 138.0, 7.3)
        _form2848_draw_text_fit(c, representative.fax, 410.0, fax_y, 151.0, 7.3)
        if representative.send_notice_copies and notice_xy is not None:
            c.setFont("Helvetica-Bold", 10.5)
            c.drawString(notice_xy[0], notice_xy[1], "X")

    # Page 1 - Line 3 tax matter rows.
    matter_row_y = [244.0, 219.5, 195.0, 170.5]
    for index, matter in enumerate(data.matters[:4]):
        y = matter_row_y[index]
        _form2848_draw_text_fit(c, matter.description, 37.0, y, 258.0, 7.7)
        _form2848_draw_text_fit(c, matter.tax_form_number, 304.0, y, 132.0, 7.7)
        _form2848_draw_text_fit(c, matter.year_or_period, 447.0, y, 122.0, 7.7)

    c.showPage()

    # Page 2 - taxpayer name and Part II representative credentials.
    _form2848_draw_text_fit(c, data.taxpayer_name, 38.0, 508.5, 230.0, 8.0)
    credential_row_y = [154.0, 130.5, 107.0, 83.5]
    for index, representative in enumerate(data.representatives[:4]):
        y = credential_row_y[index]
        _form2848_draw_centered_text_fit(
            c,
            representative.designation,
            center_x=67.0,
            y=y,
            max_width=55.0,
            font_size=8.0,
        )
        _form2848_draw_text_fit(
            c,
            representative.licensing_jurisdiction,
            104.0,
            y,
            69.0,
            7.2,
        )
        _form2848_draw_text_fit(
            c,
            representative.license_or_enrollment_number,
            181.0,
            y,
            106.0,
            7.2,
        )

    c.save()
    buffer.seek(0)
    return buffer


def form2848_fill_pdf(blank_form_path, output_path, data):
    """Merge typed Form 2848 data onto the official two-page IRS PDF."""
    if not FORM2848_PDF_SUPPORT_AVAILABLE:
        raise RuntimeError(
            "Form 2848 support requires pypdf and reportlab. "
            "Install them with: python -m pip install pypdf reportlab"
        )

    blank_form_path = Path(blank_form_path)
    output_path = Path(output_path)
    if not blank_form_path.exists():
        raise FileNotFoundError(f"Blank Form 2848 not found: {blank_form_path}")

    reader = Form2848PdfReader(str(blank_form_path))
    if len(reader.pages) < 2:
        raise ValueError("The selected Form 2848 PDF must contain at least 2 pages.")

    overlay_reader = Form2848PdfReader(form2848_build_overlay(data))
    if len(overlay_reader.pages) != 2:
        raise RuntimeError("Internal Form 2848 overlay creation failed.")

    writer = Form2848PdfWriter()
    for page_index, page in enumerate(reader.pages):
        if page_index < 2:
            page.merge_page(overlay_reader.pages[page_index])
        writer.add_page(page)

    if reader.metadata:
        try:
            writer.add_metadata(dict(reader.metadata))
        except Exception:
            pass

    output_path.parent.mkdir(parents=True, exist_ok=True)
    with output_path.open("wb") as output_file:
        writer.write(output_file)
    return output_path


class Form2848RepresentativePanel:
    """Theme-aware Tk controls for one representative and Part II credential."""

    def __init__(self, parent, number):
        self.number = number
        self.group = ttk.LabelFrame(
            parent,
            text=f"Representative {number}",
            style="Forms.TLabelframe",
            padding=12,
        )
        self.group.columnconfigure(1, weight=1)
        self.group.columnconfigure(3, weight=1)

        self.user_profile_choice = tk.StringVar()
        self.name = tk.StringVar()
        self.address1 = tk.StringVar()
        self.address2 = tk.StringVar()
        self.caf = tk.StringVar()
        self.ptin = tk.StringVar()
        self.phone = tk.StringVar()
        self.fax = tk.StringVar()
        self.copy_notices = tk.BooleanVar(value=False)
        self.designation = tk.StringVar(value=FORM2848_DESIGNATION_OPTIONS[0])
        self.jurisdiction = tk.StringVar()
        self.credential_number = tk.StringVar()

        ttk.Label(self.group, text="BabyFileCab user:").grid(
            row=0,
            column=0,
            sticky="w",
            padx=(0, 6),
            pady=(2, 7),
        )
        self.user_profile_combo = ttk.Combobox(
            self.group,
            textvariable=self.user_profile_choice,
            values=("",),
            state="readonly",
        )
        self.user_profile_combo.grid(
            row=0,
            column=1,
            columnspan=3,
            sticky="ew",
            pady=(2, 7),
        )

        labels = [
            ("Name:", self.name, 1, 0),
            ("Street address:", self.address1, 2, 0),
            ("City, State ZIP:", self.address2, 3, 0),
            ("CAF number:", self.caf, 1, 2),
            ("PTIN:", self.ptin, 2, 2),
            ("Phone:", self.phone, 3, 2),
            ("Fax:", self.fax, 4, 2),
        ]
        for label_text, variable, row, column in labels:
            ttk.Label(self.group, text=label_text).grid(
                row=row,
                column=column,
                sticky="w",
                padx=(0, 6),
                pady=4,
            )
            ttk.Entry(self.group, textvariable=variable).grid(
                row=row,
                column=column + 1,
                sticky="ew",
                padx=(0, 14) if column == 0 else (0, 0),
                pady=4,
            )

        if number <= 2:
            ttk.Checkbutton(
                self.group,
                text="Send copies of notices and communications",
                variable=self.copy_notices,
                style="Forms.TCheckbutton",
            ).grid(row=5, column=0, columnspan=4, sticky="w", pady=(6, 8))
        else:
            ttk.Label(
                self.group,
                text=(
                    "IRS notices/communications can be sent to only two "
                    "representatives."
                ),
                style="Muted.TLabel",
            ).grid(row=5, column=0, columnspan=4, sticky="w", pady=(6, 8))

        ttk.Separator(self.group, orient="horizontal").grid(
            row=6,
            column=0,
            columnspan=4,
            sticky="ew",
            pady=(2, 10),
        )
        ttk.Label(
            self.group,
            text="Part II credential",
            style="GroupTitle.TLabel",
        ).grid(row=7, column=0, columnspan=4, sticky="w", pady=(0, 7))

        ttk.Label(self.group, text="Designation:").grid(
            row=8, column=0, sticky="w", padx=(0, 6), pady=4
        )
        ttk.Combobox(
            self.group,
            textvariable=self.designation,
            values=FORM2848_DESIGNATION_OPTIONS,
            state="readonly",
            width=30,
        ).grid(row=8, column=1, sticky="ew", padx=(0, 14), pady=4)

        ttk.Label(self.group, text="Licensing jurisdiction:").grid(
            row=8, column=2, sticky="w", padx=(0, 6), pady=4
        )
        ttk.Entry(self.group, textvariable=self.jurisdiction).grid(
            row=8, column=3, sticky="ew", pady=4
        )

        ttk.Label(self.group, text="License / enrollment #:").grid(
            row=9, column=0, sticky="w", padx=(0, 6), pady=4
        )
        ttk.Entry(self.group, textvariable=self.credential_number).grid(
            row=9, column=1, sticky="ew", padx=(0, 14), pady=4
        )
        ttk.Label(
            self.group,
            text="EA: enrollment # • CPA/Attorney: license information",
            style="Muted.TLabel",
        ).grid(row=9, column=2, columnspan=2, sticky="w", pady=4)

    def set_user_choices(self, labels):
        values = [""] + list(labels)
        self.user_profile_combo.configure(values=values)

    def bind_user_selection(self, callback):
        self.user_profile_combo.bind(
            "<<ComboboxSelected>>",
            lambda event: callback(self, self.user_profile_choice.get().strip()),
        )

    def apply_user_profile(self, profile):
        first_name = str(profile.get("first_name") or "").strip()
        last_name = str(profile.get("last_name") or "").strip()
        self.name.set(f"{first_name} {last_name}".strip())
        self.address1.set(str(profile.get("street_address") or ""))
        self.address2.set(str(profile.get("city_state_zip") or ""))
        self.caf.set(str(profile.get("caf_number") or ""))
        self.ptin.set(str(profile.get("ptin") or ""))
        self.phone.set(
            str(
                profile.get("representative_phone")
                or profile.get("phone")
                or ""
            )
        )
        self.fax.set(str(profile.get("representative_fax") or ""))

    def to_data(self):
        designation_text = self.designation.get().strip()
        designation_letter = designation_text.split(" ", 1)[0].strip().lower()
        return Form2848RepresentativeData(
            name=self.name.get().strip(),
            address1=self.address1.get().strip(),
            address2=self.address2.get().strip(),
            caf_number=self.caf.get().strip(),
            ptin=self.ptin.get().strip(),
            phone=self.phone.get().strip(),
            fax=self.fax.get().strip(),
            send_notice_copies=bool(self.copy_notices.get()),
            designation=designation_letter,
            licensing_jurisdiction=self.jurisdiction.get().strip(),
            license_or_enrollment_number=self.credential_number.get().strip(),
        )

    def clear_sensitive(self):
        try:
            self.user_profile_choice.set("")
        except tk.TclError:
            pass
        for variable in (
            self.name,
            self.address1,
            self.address2,
            self.caf,
            self.ptin,
            self.phone,
            self.fax,
            self.jurisdiction,
            self.credential_number,
        ):
            variable.set("")
        self.copy_notices.set(False)


class Form2848TaxMatterRow:
    def __init__(self, parent, row_number):
        self.row_number = row_number
        self.description = tk.StringVar(value="Income" if row_number == 1 else "")
        self.tax_form = tk.StringVar(value="1040" if row_number == 1 else "")
        self.year = tk.StringVar(value="")

        ttk.Label(parent, text=str(row_number)).grid(
            row=row_number,
            column=0,
            sticky="w",
            padx=(0, 6),
            pady=4,
        )
        ttk.Combobox(
            parent,
            textvariable=self.description,
            values=FORM2848_MATTER_OPTIONS,
            state="readonly",
        ).grid(row=row_number, column=1, sticky="ew", padx=4, pady=4)
        ttk.Combobox(
            parent,
            textvariable=self.tax_form,
            values=FORM2848_TAX_FORM_OPTIONS,
            state="readonly",
            width=14,
        ).grid(row=row_number, column=2, sticky="ew", padx=4, pady=4)
        ttk.Combobox(
            parent,
            textvariable=self.year,
            values=FORM2848_YEAR_OPTIONS,
            state="normal",
            width=18,
        ).grid(row=row_number, column=3, sticky="ew", padx=4, pady=4)

    def to_data(self):
        return Form2848TaxMatterData(
            description=self.description.get().strip(),
            tax_form_number=self.tax_form.get().strip(),
            year_or_period=self.year.get().strip(),
        )

    def clear_sensitive(self):
        self.description.set("")
        self.tax_form.set("")
        self.year.set("")


