def _theme_color(widget, key, fallback):
    """Return a BabyFileCab theme color from a widget's owning app."""
    current = widget
    visited = set()

    while current is not None and id(current) not in visited:
        visited.add(id(current))

        colors = getattr(current, "colors", None)
        if isinstance(colors, dict) and key in colors:
            return colors[key]

        app = getattr(current, "app", None)
        colors = getattr(app, "colors", None)
        if isinstance(colors, dict) and key in colors:
            return colors[key]

        current = getattr(current, "master", None)

    return fallback


