def _taxcalc_style(style_name, default_name):
    mapping = {
        "Title.TLabel": "TaxCalc.Title.TLabel",
        "Heading.TLabel": "TaxCalc.Heading.TLabel",
        "Note.TLabel": "TaxCalc.Note.TLabel",
        "Primary.TButton": "TaxCalc.Primary.TButton",
    }
    if style_name:
        return mapping.get(style_name, style_name)
    return default_name


def taxcalc_frame(parent, *args, **kwargs):
    kwargs["style"] = _taxcalc_style(kwargs.get("style"), "TaxCalc.TFrame")
    return ttk.Frame(parent, *args, **kwargs)


def taxcalc_label(parent, *args, **kwargs):
    kwargs["style"] = _taxcalc_style(kwargs.get("style"), "TaxCalc.TLabel")
    return ttk.Label(parent, *args, **kwargs)


def taxcalc_labelframe(parent, *args, **kwargs):
    kwargs["style"] = _taxcalc_style(kwargs.get("style"), "TaxCalc.TLabelframe")
    return ttk.LabelFrame(parent, *args, **kwargs)


def taxcalc_entry(parent, *args, **kwargs):
    kwargs["style"] = _taxcalc_style(kwargs.get("style"), "TaxCalc.TEntry")
    return ttk.Entry(parent, *args, **kwargs)


def taxcalc_combobox(parent, *args, **kwargs):
    kwargs["style"] = _taxcalc_style(kwargs.get("style"), "TaxCalc.TCombobox")
    return ttk.Combobox(parent, *args, **kwargs)


def taxcalc_checkbutton(parent, *args, **kwargs):
    kwargs["style"] = _taxcalc_style(kwargs.get("style"), "TaxCalc.TCheckbutton")
    return ttk.Checkbutton(parent, *args, **kwargs)


def taxcalc_button(parent, *args, **kwargs):
    kwargs["style"] = _taxcalc_style(kwargs.get("style"), "TaxCalc.TButton")
