def taxcalc_notebook(parent, *args, **kwargs):
    kwargs["style"] = _taxcalc_style(kwargs.get("style"), "TaxCalc.TNotebook")
    return ttk.Notebook(parent, *args, **kwargs)


def taxcalc_scrollbar(parent, *args, **kwargs):
    orient = kwargs.get("orient", "vertical")
    default = "TaxCalc.Vertical.TScrollbar" if str(orient).lower() == "vertical" else "Horizontal.TScrollbar"
    kwargs["style"] = _taxcalc_style(kwargs.get("style"), default)
    return ttk.Scrollbar(parent, *args, **kwargs)


# ============================================================
# COMPLETE FEDERAL TAX CALCULATOR — 2025 / 2026
# Standalone desktop calculator (separate from BabyFileCab)
# ============================================================
#
# This calculator combines:
#   • ordinary federal income tax
#   • taxable interest
#   • ordinary and qualified dividends
#   • short-term and long-term capital gains/losses
#   • 0% / 15% / 20% qualified dividend & LTCG rates
#   • self-employment tax
#   • Additional Medicare Tax
#   • Foreign Tax Credit estimator (passive-category / Form 1116 concept)
#   • Net Investment Income Tax (NIIT)
#   • rental real estate and Schedule E pass-through income
#   • one partnership Schedule K-1 and one S corporation Schedule K-1
#   • qualified business income deduction (section 199A / Forms 8995 & 8995-A estimator)
#   • Child Tax Credit / Credit for Other Dependents / ACTC estimator
#   • withholding / estimated-payment balance estimate
#
# IMPORTANT:
# This is a planning/estimation tool, not a substitute for Forms 1040,
# Schedule D, Schedule SE, Form 1116, Form 8959, Form 8960, or tax software.
# It intentionally does not model every federal provision (AMT, every credit,
# itemized-deduction limitations, kiddie tax, collectibles/§1202/§1250 rates,
# every passive/basis/at-risk limitation, wash sales, PTP/cooperative QBI rules, etc.).
#
# Official IRS references used for 2025/2026 constants and formulas:
#   https://www.irs.gov/filing/federal-income-tax-rates-and-brackets
#   https://www.irs.gov/newsroom/irs-releases-tax-inflation-adjustments-for-tax-year-2026-including-amendments-from-the-one-big-beautiful-bill
#   https://www.irs.gov/irb/2024-45_IRB
#   https://www.irs.gov/irb/2025-45_IRB
#   https://www.irs.gov/publications/p550
#   https://www.irs.gov/individuals/net-investment-income-tax
#   https://www.irs.gov/individuals/international-taxpayers/foreign-tax-credit-how-to-figure-the-credit
#   https://www.irs.gov/publications/p514
#   https://www.irs.gov/instructions/i1040sse
#   https://www.irs.gov/taxtopics/tc560
# ============================================================

D = Decimal
ZERO = D("0")
ONE = D("1")
CENT = D("0.01")


def cents(value: Decimal) -> Decimal:
    return value.quantize(CENT, rounding=ROUND_HALF_UP)


def money(value: Decimal) -> str:
    return f"${cents(value):,.2f}"


def pct(value: Decimal) -> str:
    return f"{(value * D('100')):.1f}%"


