# ============================================================
# ENCRYPTION
# ============================================================

class CryptoManager:
    """
    Local at-rest encryption for BabyFileCab.

    A 32-byte (256-bit) company vault key is used with AES-GCM for both
    client metadata and document contents. AES-GCM provides confidentiality
    plus authentication, so modified ciphertext is rejected during decrypt.
    """

    KEY_SIZE = 32
    TEXT_PREFIX = "BFC1:"
    TEXT_AAD = b"BabyFileCab-Text-v1"
    VERIFIER_AAD = b"BabyFileCab-Verifier-v1"
    VERIFIER_TEXT = b"BabyFileCab unlocked"
    VAULT_FINGERPRINT_CONTEXT = b"BabyFileCab-Vault-Fingerprint-v1"
    FILE_MAGIC = b"BFCFILE1"
    FILE_NONCE_SIZE = 12
    FILE_TAG_SIZE = 16
    CHUNK_SIZE = 1024 * 1024

    def __init__(self, key: bytes):
        if len(key) != self.KEY_SIZE:
            raise ValueError(
                "BabyFileCab AES-256-GCM key must be exactly 32 bytes."
            )
        self.key = key

    @classmethod
    def is_encrypted_text(cls, value) -> bool:
        return (
            isinstance(value, str)
            and value.startswith(cls.TEXT_PREFIX)
        )

    def encrypt_tax_year(self, value) -> str:
        """Encrypt a tax-year label before it is written to SQLite."""
        if value is None or value == "":
            return ""
        return self.encrypt_text(str(value))

    def decrypt_tax_year(self, value):
        """Return an encrypted tax-year label as an int when possible."""
        text = self.decrypt_text(value)
        if text == "":
            return ""
        try:
            return int(text)
        except (TypeError, ValueError):
            return text

    # Argon2id parameters for password-derived wrapping keys.
    # 64 MiB memory, 3 iterations, and 2 lanes is intentionally expensive
    # enough to slow offline password guessing while remaining practical for
    # a local desktop application.
    ARGON2_TIME_COST = 3
    ARGON2_MEMORY_COST_KIB = 64 * 1024
    ARGON2_PARALLELISM = 2
    ARGON2_HASH_LEN = 32

    @classmethod
    def derive_key(cls, password: str, salt: bytes) -> bytes:
        """Derive a 256-bit key from a password using Argon2id."""
        return hash_secret_raw(
            secret=password.encode("utf-8"),
            salt=bytes(salt),
            time_cost=cls.ARGON2_TIME_COST,
            memory_cost=cls.ARGON2_MEMORY_COST_KIB,
            parallelism=cls.ARGON2_PARALLELISM,
            hash_len=cls.ARGON2_HASH_LEN,
            type=Argon2Type.ID,
        )

    @staticmethod
    def derive_legacy_scrypt_key(password: str, salt: bytes) -> bytes:
        """Compatibility only: unlock older BabyFileCab passwords/backups."""
        kdf = Scrypt(
            salt=bytes(salt),
            length=32,
            n=2**15,
            r=8,
            p=1,
        )
        return kdf.derive(password.encode("utf-8"))

    @classmethod
    def derive_password_key(cls, password: str, salt: bytes, kdf_name: str) -> bytes:
        normalized = (kdf_name or "scrypt").strip().lower()
        if normalized == "argon2id":
            return cls.derive_key(password, salt)
        if normalized == "scrypt":
            return cls.derive_legacy_scrypt_key(password, salt)
        raise ValueError(f"Unsupported BabyFileCab password KDF: {kdf_name}")

    USER_KEY_AAD_PREFIX = b"BabyFileCab-UserKey-v1:"

    @classmethod
    def wrap_vault_key(
        cls,
        vault_key: bytes,
        password: str,
        salt: bytes,
        username: str,
        kdf_name: str = "argon2id",
    ) -> bytes:
        """
        Encrypt the shared BabyFileCab vault key with a password-derived key.
        New accounts use Argon2id; legacy scrypt is accepted only for migration.
        The password itself is never stored.
        """
        user_key = cls.derive_password_key(password, salt, kdf_name)
        nonce = os.urandom(12)
        aad = (
            cls.USER_KEY_AAD_PREFIX
            + username.casefold().encode("utf-8")
        )
        encrypted = AESGCM(user_key).encrypt(
            nonce,
            vault_key,
            aad,
        )
        return nonce + encrypted

    @classmethod
    def unwrap_vault_key(
        cls,
        wrapped_key: bytes,
        password: str,
        salt: bytes,
        username: str,
        kdf_name: str = "argon2id",
    ) -> bytes:
        if not wrapped_key or len(wrapped_key) < 13:
            raise ValueError("Invalid BabyFileCab user key.")

        user_key = cls.derive_password_key(password, salt, kdf_name)
        nonce = bytes(wrapped_key[:12])
        encrypted = bytes(wrapped_key[12:])
        aad = (
            cls.USER_KEY_AAD_PREFIX
            + username.casefold().encode("utf-8")
        )

        return AESGCM(user_key).decrypt(
            nonce,
            encrypted,
            aad,
        )

    @classmethod
    def make_verifier(cls, key: bytes) -> bytes:
        nonce = os.urandom(12)
        encrypted = AESGCM(key).encrypt(
            nonce,
            cls.VERIFIER_TEXT,
            cls.VERIFIER_AAD,
        )
        return nonce + encrypted

    @classmethod
    def vault_key_fingerprint(cls, key: bytes) -> str:
        """Return a stable non-secret identifier for one 256-bit vault key."""
        key = bytes(key)
        if len(key) != cls.KEY_SIZE:
            raise ValueError(
                "BabyFileCab vault key must be exactly 32 bytes."
            )
        return hmac.new(
            key,
            cls.VAULT_FINGERPRINT_CONTEXT,
            hashlib.sha256,
        ).hexdigest()

    @classmethod
    def verify_key(cls, key: bytes, verifier: bytes) -> bool:
        if not verifier or len(verifier) < 13:
            return False
        nonce = verifier[:12]
        encrypted = verifier[12:]
        try:
            value = AESGCM(key).decrypt(
                nonce,
                encrypted,
                cls.VERIFIER_AAD,
            )
            return value == cls.VERIFIER_TEXT
        except (InvalidTag, ValueError):
            return False

    def encrypt_text(self, value) -> str:
        if value is None:
            return ""
        value = str(value)
        if value == "" or value.startswith(self.TEXT_PREFIX):
            return value

        nonce = os.urandom(12)
        encrypted = AESGCM(self.key).encrypt(
            nonce,
            value.encode("utf-8"),
            self.TEXT_AAD,
        )
        payload = base64.urlsafe_b64encode(
            nonce + encrypted
        ).decode("ascii")
        return self.TEXT_PREFIX + payload

    def decrypt_text(self, value) -> str:
        if value is None:
            return ""
        value = str(value)
        if value == "" or not value.startswith(self.TEXT_PREFIX):
            # Plaintext support is intentional for one-time migration from
            # older BabyFileCab development versions.
            return value

        raw = base64.urlsafe_b64decode(
            value[len(self.TEXT_PREFIX):].encode("ascii")
        )
        nonce = raw[:12]
        encrypted = raw[12:]
        plaintext = AESGCM(self.key).decrypt(
            nonce,
            encrypted,
            self.TEXT_AAD,
        )
        return plaintext.decode("utf-8")

    def encrypt_file(self, source: Path, destination: Path):
        destination.parent.mkdir(parents=True, exist_ok=True)
        temp_path = destination.with_suffix(destination.suffix + ".tmp")
        nonce = os.urandom(self.FILE_NONCE_SIZE)

        try:
            with source.open("rb") as src, temp_path.open("wb") as dst:
                dst.write(self.FILE_MAGIC)
                dst.write(nonce)

                encryptor = Cipher(
                    algorithms.AES(self.key),
                    modes.GCM(nonce),
                ).encryptor()
                encryptor.authenticate_additional_data(self.FILE_MAGIC)

                while True:
                    chunk = src.read(self.CHUNK_SIZE)
                    if not chunk:
                        break
                    dst.write(encryptor.update(chunk))

                dst.write(encryptor.finalize())
                dst.write(encryptor.tag)

            try:
                os.chmod(temp_path, 0o600)
            except OSError:
                pass

            temp_path.replace(destination)

        except Exception:
            try:
                temp_path.unlink(missing_ok=True)
            except OSError:
                pass
            raise

    def decrypt_file(self, source: Path, destination: Path):
        size = source.stat().st_size
        header_size = len(self.FILE_MAGIC) + self.FILE_NONCE_SIZE
        minimum_size = header_size + self.FILE_TAG_SIZE

        if size < minimum_size:
            raise ValueError("Encrypted BabyFileCab file is incomplete.")

        destination.parent.mkdir(parents=True, exist_ok=True)
        temp_path = destination.with_suffix(destination.suffix + ".tmp")

        try:
            with source.open("rb") as src:
                magic = src.read(len(self.FILE_MAGIC))
                if magic != self.FILE_MAGIC:
                    raise ValueError("This file is not a BabyFileCab encrypted file.")

                nonce = src.read(self.FILE_NONCE_SIZE)
                src.seek(-self.FILE_TAG_SIZE, os.SEEK_END)
                tag = src.read(self.FILE_TAG_SIZE)

                ciphertext_length = (
                    size - header_size - self.FILE_TAG_SIZE
                )
                src.seek(header_size)

                decryptor = Cipher(
                    algorithms.AES(self.key),
                    modes.GCM(nonce, tag),
                ).decryptor()
                decryptor.authenticate_additional_data(self.FILE_MAGIC)

                remaining = ciphertext_length
                with temp_path.open("wb") as dst:
                    while remaining > 0:
                        chunk = src.read(
                            min(self.CHUNK_SIZE, remaining)
                        )
                        if not chunk:
                            raise ValueError(
                                "Encrypted BabyFileCab file ended unexpectedly."
                            )
                        remaining -= len(chunk)
                        dst.write(decryptor.update(chunk))

                    dst.write(decryptor.finalize())

            try:
                os.chmod(temp_path, 0o600)
            except OSError:
                pass

            temp_path.replace(destination)

        except Exception:
            try:
                temp_path.unlink(missing_ok=True)
            except OSError:
                pass
            raise

    @classmethod
    def is_encrypted_file(cls, path: Path) -> bool:
        try:
            with path.open("rb") as handle:
                return handle.read(len(cls.FILE_MAGIC)) == cls.FILE_MAGIC
        except OSError:
            return False


class EncryptedBackupWriter:
    """
    Streaming writer for BabyFileCab .bfcbak files.

    File format (version 2):
        magic (8 bytes)
        Argon2id salt (16 bytes)
        AES-GCM nonce (12 bytes)
        encrypted TAR stream (variable length)
        AES-GCM tag (16 bytes)

    The TAR stream contains all client names, folder names, metadata, and
    document contents, so none of that information is visible without the
    backup password. The header contains only random cryptographic values.
    """

    LEGACY_MAGIC = b"BFCBAK1!"
    MAGIC = b"BFCBAK2!"
    SALT_SIZE = 16
    NONCE_SIZE = 12
    TAG_SIZE = 16
    CHUNK_SIZE = 1024 * 1024

    def __init__(self, destination: Path, password: str):
        if not password:
            raise ValueError("A backup password is required.")

        self.destination = Path(destination)
        self.destination.parent.mkdir(parents=True, exist_ok=True)
        self._raw = self.destination.open("wb")
        self._closed = False
        self._position = 0

        self.salt = os.urandom(self.SALT_SIZE)
        self.nonce = os.urandom(self.NONCE_SIZE)
        self.header = self.MAGIC + self.salt + self.nonce
        key = CryptoManager.derive_key(password, self.salt)

        self._encryptor = Cipher(
            algorithms.AES(key),
            modes.GCM(self.nonce),
        ).encryptor()
        self._encryptor.authenticate_additional_data(self.header)
        self._raw.write(self.header)

        try:
            os.chmod(self.destination, 0o600)
        except OSError:
            pass

    @property
    def closed(self):
        return self._closed

    def writable(self):
        return True

    def seekable(self):
        return False

    def tell(self):
        return self._position

    def write(self, data):
        if self._closed:
            raise ValueError("I/O operation on closed encrypted backup.")

        if not data:
            return 0

        payload = bytes(data)
        encrypted = self._encryptor.update(payload)
        if encrypted:
            self._raw.write(encrypted)
        self._position += len(payload)
        return len(payload)

    def flush(self):
        if not self._closed:
            self._raw.flush()

    def close(self):
        if self._closed:
            return

        try:
            final_bytes = self._encryptor.finalize()
            if final_bytes:
                self._raw.write(final_bytes)
            self._raw.write(self._encryptor.tag)
            self._raw.flush()
            try:
                os.fsync(self._raw.fileno())
            except OSError:
                pass
        finally:
            self._raw.close()
            self._closed = True

    @classmethod
    def verify(cls, backup_path: Path, password: str):
        """Read and authenticate an entire .bfcbak without writing plaintext.

        Version 2 backups use Argon2id. Version 1 scrypt backups remain
        readable so existing customer backups are not invalidated.
        """
        backup_path = Path(backup_path)
        size = backup_path.stat().st_size
        header_size = len(cls.MAGIC) + cls.SALT_SIZE + cls.NONCE_SIZE
        minimum_size = header_size + cls.TAG_SIZE

        if size < minimum_size:
            raise ValueError("Encrypted BabyFileCab backup is incomplete.")

        with backup_path.open("rb") as src:
            magic = src.read(len(cls.MAGIC))
            if magic not in {cls.MAGIC, cls.LEGACY_MAGIC}:
                raise ValueError("This is not a supported BabyFileCab encrypted backup.")

            salt = src.read(cls.SALT_SIZE)
            nonce = src.read(cls.NONCE_SIZE)
            header = magic + salt + nonce

            src.seek(-cls.TAG_SIZE, os.SEEK_END)
            tag = src.read(cls.TAG_SIZE)
            ciphertext_length = size - header_size - cls.TAG_SIZE
            src.seek(header_size)

            if magic == cls.MAGIC:
                key = CryptoManager.derive_key(password, salt)
            else:
                key = CryptoManager.derive_legacy_scrypt_key(password, salt)

            decryptor = Cipher(
                algorithms.AES(key),
                modes.GCM(nonce, tag),
            ).decryptor()
            decryptor.authenticate_additional_data(header)

            remaining = ciphertext_length
            while remaining > 0:
                chunk = src.read(min(cls.CHUNK_SIZE, remaining))
                if not chunk:
                    raise ValueError("Encrypted backup ended unexpectedly.")
                remaining -= len(chunk)
                decryptor.update(chunk)

            decryptor.finalize()



class EncryptedDocumentReader:
    """Expose one encrypted BabyFileCab document as a plaintext read stream."""

    def __init__(self, crypto: CryptoManager, source: Path):
        self.crypto = crypto
        self.source = Path(source)
        self._src = self.source.open("rb")
        self._closed = False
        self._finalized = False

        size = self.source.stat().st_size
        header_size = len(crypto.FILE_MAGIC) + crypto.FILE_NONCE_SIZE
        minimum_size = header_size + crypto.FILE_TAG_SIZE
        if size < minimum_size:
            self._src.close()
            raise ValueError("Encrypted BabyFileCab file is incomplete.")

        magic = self._src.read(len(crypto.FILE_MAGIC))
        if magic != crypto.FILE_MAGIC:
            self._src.close()
            raise ValueError("This file is not a BabyFileCab encrypted file.")

        nonce = self._src.read(crypto.FILE_NONCE_SIZE)
        self._src.seek(-crypto.FILE_TAG_SIZE, os.SEEK_END)
        tag = self._src.read(crypto.FILE_TAG_SIZE)

        self.size = size - header_size - crypto.FILE_TAG_SIZE
        self._remaining = self.size
        self._src.seek(header_size)

        self._decryptor = Cipher(
            algorithms.AES(crypto.key),
            modes.GCM(nonce, tag),
        ).decryptor()
        self._decryptor.authenticate_additional_data(crypto.FILE_MAGIC)

    def readable(self):
        return True

    def read(self, size=-1):
        if self._closed:
            return b""

        if self._remaining <= 0:
            if not self._finalized:
                self._decryptor.finalize()
                self._finalized = True
            return b""

        if size is None or size < 0:
            size = self._remaining
        else:
            size = min(size, self._remaining)

        chunk = self._src.read(size)
        if not chunk:
            raise ValueError("Encrypted document ended unexpectedly.")

        self._remaining -= len(chunk)
        plaintext = self._decryptor.update(chunk)

        if self._remaining == 0 and not self._finalized:
            plaintext += self._decryptor.finalize()
            self._finalized = True

        return plaintext

    def close(self):
        if self._closed:
            return
        try:
            # If the entire document was read, finalization already verified
            # its authentication tag. A partial read is simply abandoned.
            self._src.close()
        finally:
            self._closed = True



class MasterPasswordDialog(tk.Toplevel):
    def __init__(self, parent, creating=False):
        super().__init__(parent)

        self.parent = parent
        self.creating = creating
        self.result = None

        self.title(
            "Create BabyFileCab Password"
            if creating
            else "Unlock BabyFileCab"
        )
        self.configure(background=_theme_color(self, "bg", "#0f172a"))
        self.resizable(False, False)
        self.transient(parent)
        self.grab_set()

        frame = ttk.Frame(
            self,
            padding=22,
            style="Card.TFrame",
        )
        frame.pack(fill="both", expand=True)

        ttk.Label(
            frame,
            text=(
                "Protect BabyFileCab"
                if creating
                else "Unlock BabyFileCab"
            ),
            style="PreviewTitle.TLabel",
        ).grid(
            row=0,
            column=0,
            columnspan=2,
            sticky="w",
            pady=(0, 8),
        )

        message = (
            "Create a master password. BabyFileCab does not store the "
            "password and cannot recover it if it is forgotten."
            if creating
            else
            "Enter your master password to decrypt your local BabyFileCab data."
        )

        ttk.Label(
            frame,
            text=message,
            style="Muted.TLabel",
            wraplength=430,
            justify="left",
        ).grid(
            row=1,
            column=0,
            columnspan=2,
            sticky="w",
            pady=(0, 14),
        )

        ttk.Label(
            frame,
            text="Master Password:",
        ).grid(
            row=2,
            column=0,
            sticky="w",
            padx=(0, 10),
            pady=6,
        )

        self.password_entry = ttk.Entry(
            frame,
            show="•",
            width=34,
        )
        self.password_entry.grid(
            row=2,
            column=1,
            sticky="ew",
            pady=6,
        )

        self.confirm_entry = None
        next_row = 3

        if creating:
            ttk.Label(
                frame,
                text="Confirm Password:",
            ).grid(
                row=3,
                column=0,
                sticky="w",
                padx=(0, 10),
                pady=6,
            )

            self.confirm_entry = ttk.Entry(
                frame,
                show="•",
                width=34,
            )
            self.confirm_entry.grid(
                row=3,
                column=1,
                sticky="ew",
                pady=6,
            )
            next_row = 4

        buttons = ttk.Frame(
            frame,
            style="Card.TFrame",
        )
        buttons.grid(
            row=next_row,
            column=0,
            columnspan=2,
            sticky="e",
            pady=(16, 0),
        )

        ttk.Button(
            buttons,
            text="Cancel",
            command=self.cancel,
        ).pack(side="right", padx=(6, 0))

        ttk.Button(
            buttons,
            text=("Create Password" if creating else "Unlock"),
            style="Primary.TButton",
            command=self.submit,
        ).pack(side="right")

        frame.columnconfigure(1, weight=1)

        # Standard Cut / Copy / Paste menu for every client-information field.
        # This is especially useful from File > Copy Client, where the selected
        # client's information is prefilled for reuse.
        editable_entries = (
            self.first_entry,
            self.last_entry,
            self.business_entry,
            self.address1_entry,
            self.address2_entry,
            self.tax_id_entry,
            self.email_entry,
            self.phone_entry,
            self.start_year_entry,
        )

        def show_edit_menu(event):
            widget = event.widget
            menu = tk.Menu(self, tearoff=0)
            menu.add_command(
                label="Cut",
                command=lambda: widget.event_generate("<<Cut>>"),
            )
            menu.add_command(
                label="Copy",
                command=lambda: widget.event_generate("<<Copy>>"),
            )
            menu.add_command(
                label="Paste",
                command=lambda: widget.event_generate("<<Paste>>"),
            )
            menu.add_separator()
            menu.add_command(
                label="Select All",
                command=lambda: (
                    widget.selection_range(0, "end"),
                    widget.icursor("end"),
                ),
            )
            try:
                menu.tk_popup(event.x_root, event.y_root)
            finally:
                menu.grab_release()
            return "break"

        for entry in editable_entries:
            entry.bind("<Button-3>", show_edit_menu)

        self.bind("<Escape>", lambda event: self.cancel())
        self.bind("<Return>", lambda event: self.submit())
        self.protocol("WM_DELETE_WINDOW", self.cancel)

        self.update_idletasks()
        x = parent.winfo_rootx() + max(
            40,
            (parent.winfo_width() - self.winfo_width()) // 2,
        )
        y = parent.winfo_rooty() + max(
            40,
            (parent.winfo_height() - self.winfo_height()) // 3,
        )
        self.geometry(f"+{x}+{y}")
        self.password_entry.focus_set()
        self.wait_window(self)

    def submit(self):
        password = self.password_entry.get()

        if self.creating:
            if len(password) < 8:
                messagebox.showwarning(
                    "Master Password",
                    "Use at least 8 characters for the master password.",
                    parent=self,
                )
                return

            if password != self.confirm_entry.get():
                messagebox.showwarning(
                    "Master Password",
                    "The two passwords do not match.",
                    parent=self,
                )
                return

        if not password:
            return

        self.result = password
        self.destroy()

    def cancel(self):
        self.result = None
        self.destroy()



